changeSet.sql:
ALTER TABLE clinlims.label_preset DROP CONSTRAINT label_preset_scope_required;
ALTER TABLE clinlims.label_preset ADD CONSTRAINT label_preset_scope_required CHECK(prints_per_order OR prints_per_sample OR prints_per_container);
ALTER TABLE clinlims.label_preset ADD CONSTRAINT label_preset_container_counts CHECK(default_per_container >= 0 AND max_per_container >= default_per_container);

rollback.sql:
DO $$ BEGIN
IF EXISTS(SELECT 1 FROM clinlims.micro_incoming_item) OR EXISTS(SELECT 1 FROM clinlims.workplan_print_record) OR EXISTS(SELECT 1 FROM clinlims.micro_bench_action) OR EXISTS(SELECT 1 FROM clinlims.label_preset WHERE prints_per_container) THEN RAISE EXCEPTION 'M7 rollback would discard history or container configuration; retain it before rollback'; END IF;
END $$;

ALTER TABLE clinlims.label_preset DROP CONSTRAINT label_preset_scope_required;
ALTER TABLE clinlims.label_preset DROP CONSTRAINT label_preset_container_counts;
ALTER TABLE clinlims.label_preset ADD CONSTRAINT label_preset_scope_required CHECK(prints_per_order OR prints_per_sample);

DO $$ BEGIN
IF EXISTS(SELECT 1 FROM clinlims.micro_incoming_item) OR EXISTS(SELECT 1 FROM clinlims.workplan_print_record) OR EXISTS(SELECT 1 FROM clinlims.micro_bench_action) OR EXISTS (SELECT 1 FROM clinlims.label_preset p WHERE p.name='Culture Plate Label' AND p.id IN (SELECT preset_id FROM clinlims.micro_container_preset_seed) AND (NOT p.is_system OR NOT p.is_active OR NOT p.prints_per_container OR p.is_universal OR p.barcode_type<>'QR' OR p.default_per_order<>0 OR p.max_per_order<>10 OR p.default_per_sample<>0 OR p.max_per_sample<>10 OR p.height_mm<>25 OR p.width_mm<>50 OR p.default_per_container<>0 OR p.max_per_container<>10 OR p.prints_per_order OR p.prints_per_sample OR EXISTS(SELECT 1 FROM clinlims.label_preset_field f WHERE f.preset_id=p.id) OR EXISTS(SELECT 1 FROM clinlims.test_label_preset_link l WHERE l.preset_id=p.id))) THEN RAISE EXCEPTION 'M7 history or configured container preset must be retained before rollback'; END IF;
END $$;

DO $$ BEGIN
IF EXISTS(SELECT 1 FROM clinlims.micro_incoming_item) OR EXISTS(SELECT 1 FROM clinlims.workplan_print_record) OR EXISTS(SELECT 1 FROM clinlims.micro_bench_action) OR EXISTS (SELECT 1 FROM clinlims.label_preset p WHERE p.name='Isolate Label' AND p.id IN (SELECT preset_id FROM clinlims.micro_container_preset_seed) AND (NOT p.is_system OR NOT p.is_active OR NOT p.prints_per_container OR p.is_universal OR p.barcode_type<>'QR' OR p.default_per_order<>0 OR p.max_per_order<>10 OR p.default_per_sample<>0 OR p.max_per_sample<>10 OR p.height_mm<>25 OR p.width_mm<>50 OR p.default_per_container<>0 OR p.max_per_container<>10 OR p.prints_per_order OR p.prints_per_sample OR EXISTS(SELECT 1 FROM clinlims.label_preset_field f WHERE f.preset_id=p.id) OR EXISTS(SELECT 1 FROM clinlims.test_label_preset_link l WHERE l.preset_id=p.id))) THEN RAISE EXCEPTION 'M7 history or configured container preset must be retained before rollback'; END IF;
END $$;

DO $$ BEGIN
IF EXISTS(SELECT 1 FROM clinlims.micro_incoming_item) OR EXISTS(SELECT 1 FROM clinlims.workplan_print_record) OR EXISTS(SELECT 1 FROM clinlims.micro_bench_action) OR EXISTS (SELECT 1 FROM clinlims.label_preset p WHERE p.name='AST Panel Label' AND p.id IN (SELECT preset_id FROM clinlims.micro_container_preset_seed) AND (NOT p.is_system OR NOT p.is_active OR NOT p.prints_per_container OR p.is_universal OR p.barcode_type<>'QR' OR p.default_per_order<>0 OR p.max_per_order<>10 OR p.default_per_sample<>0 OR p.max_per_sample<>10 OR p.height_mm<>25 OR p.width_mm<>50 OR p.default_per_container<>0 OR p.max_per_container<>10 OR p.prints_per_order OR p.prints_per_sample OR EXISTS(SELECT 1 FROM clinlims.label_preset_field f WHERE f.preset_id=p.id) OR EXISTS(SELECT 1 FROM clinlims.test_label_preset_link l WHERE l.preset_id=p.id))) THEN RAISE EXCEPTION 'M7 history or configured container preset must be retained before rollback'; END IF;
END $$;
